import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { usePopper } from 'react-popper';
import classnames from 'clsx';
import {
  AlignItems,
  BackgroundColor,
  BorderColor,
  BorderRadius,
  Display,
  JustifyContent,
} from '../../../helpers/constants/design-system';

import { Box } from '../box';
import type { BoxProps, PolymorphicRef } from '../box';

import {
  PopoverProps,
  PopoverComponent,
  PopoverPosition,
  PopoverRole,
} from './popover.types';

const CAPTURE_EVENT_LISTENER_OPTIONS = { capture: true };

/**
 * @deprecated This component is deprecated and will be removed in a future release.
 * Please use the Popover component from @metamask/design-system-react instead.
 * @see {@link https://github.com/MetaMask/metamask-design-system/blob/main/packages/design-system-react/MIGRATION.md#popover-component | Migration Guide}
 * @see {@link https://metamask.github.io/metamask-design-system/?path=/docs/react-components-popover--docs | Storybook Documentation}
 * @see {@link https://github.com/MetaMask/metamask-design-system/tree/main/packages/design-system-react/src/components/Popover | Component Source}
 */
export const Popover: PopoverComponent = React.forwardRef(
  // TODO: Fix in https://github.com/MetaMask/metamask-extension/issues/31860
  // eslint-disable-next-line @typescript-eslint/naming-convention
  <C extends React.ElementType = 'div'>(
    {
      children,
      className = '',
      position = PopoverPosition.Auto,
      role = PopoverRole.Tooltip,
      hasArrow = false,
      matchWidth,
      preventOverflow = false,
      offset = [0, 8],
      flip = false,
      referenceHidden = true,
      referenceElement,
      isOpen,
      title,
      isPortal = false,
      arrowProps,
      onClickOutside,
      onPressEscKey,
      ...props
    }: PopoverProps<C>,
    ref?: PolymorphicRef<C>,
  ) => {
    const [popperElement, setPopperElement] = useState<HTMLElement | null>(
      null,
    );
    const [arrowElement, setArrowElement] = useState<HTMLElement | null>(null);
    const popoverRef = React.useRef<HTMLElement | null>(null);

    // Define Popper options
    const { styles, attributes } = usePopper(referenceElement, popperElement, {
      placement: position,
      modifiers: [
        {
          name: 'preventOverflow',
          enabled: position === PopoverPosition.Auto ? true : preventOverflow,
        },
        {
          name: 'flip',
          enabled: position === PopoverPosition.Auto ? true : flip,
        },
        {
          name: 'arrow',
          enabled: hasArrow,
          options: {
            element: arrowElement,
          },
        },
        {
          name: 'offset',
          options: {
            offset,
          },
        },
      ],
    });

    // Define width to match reference element or auto
    const contentStyle = {
      width: matchWidth ? referenceElement?.clientWidth : 'auto',
    };

    useEffect(() => {
      if (!isOpen || (!onPressEscKey && !onClickOutside)) {
        return undefined;
      }

      // Esc key press
      const handleEscKey = (event: KeyboardEvent) => {
        if (event.key === 'Escape') {
          onPressEscKey?.();
        }
      };

      const handleClickOutside = (event: MouseEvent) => {
        if (
          popoverRef.current &&
          !popoverRef.current.contains(event.target as Node) &&
          !referenceElement?.contains(event.target as Node)
        ) {
          onClickOutside?.();
        }
      };

      if (onPressEscKey) {
        document.addEventListener(
          'keydown',
          handleEscKey,
          CAPTURE_EVENT_LISTENER_OPTIONS,
        );
      }

      if (onClickOutside) {
        document.addEventListener(
          'click',
          handleClickOutside,
          CAPTURE_EVENT_LISTENER_OPTIONS,
        );
      }

      return () => {
        if (onPressEscKey) {
          document.removeEventListener(
            'keydown',
            handleEscKey,
            CAPTURE_EVENT_LISTENER_OPTIONS,
          );
        }

        if (onClickOutside) {
          document.removeEventListener(
            'click',
            handleClickOutside,
            CAPTURE_EVENT_LISTENER_OPTIONS,
          );
        }
      };
    }, [onPressEscKey, isOpen, onClickOutside, referenceElement]);

    const PopoverContent = (
      <Box
        borderColor={BorderColor.borderMuted}
        borderRadius={BorderRadius.LG}
        backgroundColor={BackgroundColor.backgroundElevated2}
        padding={4}
        role={role}
        className={classnames(
          'mm-popover',
          {
            'mm-popover--open': Boolean(isOpen),
            'mm-popover--reference-hidden': Boolean(referenceHidden),
          },
          className,
        )}
        ref={(element: PolymorphicRef<C>) => {
          if (ref) {
            if (typeof ref === 'function') {
              ref(element);
            } else {
              (ref as React.MutableRefObject<C | null>).current = element;
            }
          }
          setPopperElement(element);
          popoverRef.current = element;
        }}
        {...attributes.popper}
        {...(props as BoxProps<C>)}
        style={{ ...styles.popper, ...contentStyle, ...props.style }}
      >
        {children}
        {hasArrow && (
          <Box
            borderColor={BorderColor.borderMuted}
            className={classnames('mm-popover__arrow')}
            ref={setArrowElement}
            display={Display.Flex}
            justifyContent={JustifyContent.center}
            alignItems={AlignItems.center}
            style={styles.arrow}
            {...attributes.arrow}
            {...(arrowProps as BoxProps<'div'>)}
          />
        )}
      </Box>
    );

    return (
      <>
        {isPortal
          ? isOpen && createPortal(PopoverContent, document.body)
          : isOpen && PopoverContent}
      </>
    );
  },
);
